//! Shows Ferris on the 100x64 LCD, then idles keeping the AVR link alive.
//!
//! Build as a bootloader app (`just app-build nxt-lcd`) and upload with
//! `just app-upload nxt-lcd`. Holding Left+Right for a second re-enters the USB
//! bootloader so the app can be replaced again. Holding Cancel for two
//! seconds powers the brick off (Orange boots it again). The bitmap in `ferris.rs`
//! is generated by `tools/img2lcd/convert.sh`.
#![no_std]
#![no_main]

use nxt_hal::avr::{AvrLink, Button, Hold};
use nxt_hal::bootloader;
use nxt_hal::lcd::Lcd;
use nxt_hal::{Peripherals, Pit};

// Pulled in only for its side effects: the vector table and reset handler.
extern crate nxt_rt as _;

mod ferris;

#[no_mangle]
pub extern "C" fn main() -> ! {
    let peripherals = Peripherals::take().expect("Peripherals::take must only be called once");
    let mut pmc = peripherals.pmc;
    let mut wdt = peripherals.wdt;

    wdt.disable();
    pmc.init_clocks();

    // The AVR must keep hearing from us or it makes the "clicking brick"
    // noise and eventually powers the brick down, so every wait below
    // services the link.
    let pit = Pit::new_1ms();
    let mut avr = AvrLink::new(&mut pmc);

    let mut lcd = Lcd::new(
        pmc.enable_spi_clock(),
        pmc.enable_pioa_clock(),
        &pit,
        || avr.service(&pit),
    );
    lcd.flush(&ferris::FERRIS);

    // Holding Left+Right this long restarts into the USB bootloader (only when
    // linked behind it; see `bootloader::available`).
    const FLASH_MODE_HOLD_MS: u32 = 1000;
    const POWER_OFF_HOLD_MS: u32 = 2000;
    let mut chord = Hold::default();
    let mut cancel_ms: u32 = 0;
    let mut last_tick = pit.ticks();
    loop {
        avr.service(&pit);
        let t = pit.ticks();
        if t != last_tick {
            last_tick = t;
            let held_ms = chord.update(avr.button() == Button::LeftRight);
            cancel_ms = if avr.button() == Button::Cancel {
                cancel_ms + 1
            } else {
                0
            };
            if cancel_ms >= POWER_OFF_HOLD_MS {
                lcd.shutdown(&pit, || avr.service(&pit));
                avr.power_off(&pit);
            }
            if held_ms >= FLASH_MODE_HOLD_MS && bootloader::available() {
                bootloader::enter(&mut pmc);
            }
        }
    }
}
